1	import http from 'node:http';
2	import { SnapshotError, Workspace } from './workspace.js';
3	import { sameDocument } from './history.js';
4	
5	const MAX_BODY_BYTES = 1024 * 1024;
6	const ETAG_PATTERN = /^"[0-9a-f]{64}"$/u;
7	const ID_PATTERN = /^[a-z0-9][a-z0-9._-]*$/u;
8	const DOCUMENT_FIELDS = new Set(['id', 'title', 'body', 'tags']);
9	const BATCH_ACTIONS = new Set(['create', 'replace', 'delete', 'restore']);
10	const MAX_BATCH_OPERATIONS = 100;
11	
12	class HttpError extends Error {
13	  constructor(status, code, message) {
14	    super(message);
15	    this.name = 'HttpError';
16	    this.status = status;
17	    this.code = code;
18	  }
19	}
20	
21	function sendJson(res, status, payload, etag) {
22	  const headers = { 'content-type': 'application/json; charset=utf-8' };
23	  if (etag) headers.etag = etag;
24	  res.writeHead(status, headers);
25	  res.end(JSON.stringify(payload));
26	}
27	
28	async function readBody(req) {
29	  const declared = Number(req.headers['content-length']);
30	  if (Number.isFinite(declared) && declared > MAX_BODY_BYTES) {
31	    req.resume();
32	    throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
33	  }
34	  const chunks = [];
35	  let size = 0;
36	  for await (const chunk of req) {
37	    size += chunk.length;
38	    if (size > MAX_BODY_BYTES) {
39	      throw new HttpError(413, 'PAYLOAD_TOO_LARGE', 'request body exceeds 1 MiB');
40	    }
41	    chunks.push(chunk);
42	  }
43	  return Buffer.concat(chunks).toString('utf8');
44	}
45	
46	function parseJson(text) {
47	  try {
48	    return JSON.parse(text);
49	  } catch {
50	    throw new HttpError(400, 'INVALID_JSON', 'request body is not valid JSON');
51	  }
52	}
53	
54	function validateDocument(data) {
55	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
56	    throw new HttpError(400, 'INVALID_DOCUMENT', 'document must be an object');
57	  }
58	  for (const key of Object.keys(data)) {
59	    if (!DOCUMENT_FIELDS.has(key)) {
60	      throw new HttpError(400, 'INVALID_DOCUMENT', `unknown document field: ${key}`);
61	    }
62	  }
63	  for (const key of ['id', 'title', 'body']) {
64	    if (typeof data[key] !== 'string' || !data[key].trim()) {
65	      throw new HttpError(400, 'INVALID_DOCUMENT', `${key} must be a non-empty string`);
66	    }
67	  }
68	  if (!ID_PATTERN.test(data.id)) {
69	    throw new HttpError(400, 'INVALID_DOCUMENT', 'id must be URL-safe lowercase text');
70	  }
71	  if (data.tags !== undefined && (!Array.isArray(data.tags) || data.tags.some((tag) => typeof tag !== 'string'))) {
72	    throw new HttpError(400, 'INVALID_DOCUMENT', 'tags must be an array of strings');
73	  }
74	  return { id: data.id, title: data.title, body: data.body, tags: data.tags ?? [] };
75	}
76	
77	// Validates the batch envelope and every operation, returning normalized
78	// `{ operations, dryRun }`. Structural problems (bad envelope shape, unknown
79	// type, wrong fields, missing id, non-string id) are INVALID_BATCH; document
80	// content problems follow the single-document rules (INVALID_DOCUMENT), and a
81	// revision that is not a positive integer is INVALID_REVISION.
82	function validateBatchRequest(data) {
83	  if (!data || typeof data !== 'object' || Array.isArray(data)) {
84	    throw new HttpError(400, 'INVALID_BATCH', 'batch body must be an object');
85	  }
86	  for (const key of Object.keys(data)) {
87	    if (key !== 'operations' && key !== 'dryRun') {
88	      throw new HttpError(400, 'INVALID_BATCH', `unknown batch field: ${key}`);
89	    }
90	  }
91	  if (!Array.isArray(data.operations)) {
92	    throw new HttpError(400, 'INVALID_BATCH', 'operations must be an array');
93	  }
94	  if (data.operations.length < 1 || data.operations.length > MAX_BATCH_OPERATIONS) {
95	    throw new HttpError(400, 'INVALID_BATCH', `operations must contain 1 to ${MAX_BATCH_OPERATIONS} items`);
96	  }
97	  const dryRun = data.dryRun === undefined ? false : data.dryRun;
98	  if (typeof dryRun !== 'boolean') {
99	    throw new HttpError(400, 'INVALID_BATCH', 'dryRun must be a boolean');
100	  }
101	
102	  const operations = data.operations.map((op, index) => {
103	    if (!op || typeof op !== 'object' || Array.isArray(op)) {
104	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] must be an object`);
105	    }
106	    const type = op.type;
107	    if (typeof type !== 'string' || !BATCH_ACTIONS.has(type)) {
108	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has an unknown type`);
109	    }
110	    const expectedKeys = type === 'create' || type === 'replace'
111	      ? ['type', 'document']
112	      : type === 'delete'
113	        ? ['type', 'id']
114	        : ['type', 'id', 'revision'];
115	    const keys = Object.keys(op);
116	    if (keys.length !== expectedKeys.length || !expectedKeys.every((key) => keys.includes(key))) {
117	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] has invalid fields for ${type}`);
118	    }
119	
120	    if (type === 'create' || type === 'replace') {
121	      if (!op.document || typeof op.document !== 'object' || Array.isArray(op.document)) {
122	        throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] document must be an object`);
123	      }
124	      return { type, document: validateDocument(op.document) };
125	    }
126	
127	    if (typeof op.id !== 'string') {
128	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] id must be a string`);
129	    }
130	
131	    if (type === 'delete') {
132	      return { type, id: op.id };
133	    }
134	
135	    // restore: the envelope is structurally valid; the revision value itself
136	    // follows the single-document restore rules.
137	    if (op.revision === undefined) {
138	      throw new HttpError(400, 'INVALID_BATCH', `operations[${index}] restore requires a revision`);
139	    }
140	    if (!Number.isInteger(op.revision) || op.revision < 1) {
141	      throw new HttpError(400, 'INVALID_REVISION', `operations[${index}] revision must be a positive integer`);
142	    }
143	    return { type, id: op.id, revision: op.revision };
144	  });
145	
146	  // Every operation targets a distinct document id.
147	  const seen = new Set();
148	  for (const op of operations) {
149	    const id = op.type === 'create' || op.type === 'replace' ? op.document.id : op.id;
150	    if (seen.has(id)) {
151	      throw new HttpError(400, 'INVALID_BATCH', `duplicate target id in batch: ${id}`);
152	    }
153	    seen.add(id);
154	  }
155	
156	  return { operations, dryRun };
157	}
158	
159	// A document server holds one Workspace and, when a history store is supplied,
160	// a per-document revision ledger. Every committed change is persisted through
161	// `save(snapshot, historySnapshot)` before the in-memory state is swapped, so a
162	// failed save leaves memory, queries, history, and the original files
163	// untouched. Everything here is synchronous, so a commit is atomic with
164	// respect to other requests.
165	export function createDocumentServer({ workspace, save, history = null }) {
166	  let current = workspace;
167	  let ledger = history;
168	
169	  const currentEtag = () => `"${current.exportJSON().checksum}"`;
170	
171	  function requireIfMatch(req) {
172	    const value = req.headers['if-match'];
173	    if (value === undefined) {
174	      throw new HttpError(428, 'PRECONDITION_REQUIRED', 'write requests require an If-Match header');
175	    }
176	    if (!ETAG_PATTERN.test(value)) {
177	      throw new HttpError(400, 'INVALID_IF_MATCH', 'If-Match must be a double-quoted checksum');
178	    }
179	    if (value !== currentEtag()) {
180	      throw new HttpError(412, 'PRECONDITION_FAILED', 'If-Match checksum is stale');
181	    }
182	  }
183	
184	  function assertTitleFree(candidate, title) {
185	    const trimmed = title.trim();
186	    for (const existing of candidate.list()) {
187	      if (existing.title === trimmed) {
188	        throw new HttpError(409, 'CONFLICT', `title already in use: ${trimmed}`);
189	      }
190	    }
191	  }
192	
193	  // Builds the next state on a candidate workspace and lets `mutate` append to
194	  // the next ledger. The callback returns false to signal a content-preserving
195	  // write (normalized content unchanged): the request still succeeds, but no
196	  // revision is appended and nothing is persisted.
197	  function commit(mutate) {
198	    const candidate = new Workspace();
199	    for (const document of current.list()) candidate.add(document);
200	    const nextLedger = ledger ? ledger.clone() : null;
201	    const changed = mutate(candidate, nextLedger);
202	    if (changed === false) {
203	      return current.exportJSON();
204	    }
205	    const snapshot = candidate.exportJSON();
206	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
207	    current = candidate;
208	    ledger = nextLedger;
209	    return snapshot;
210	  }
211	
212	  // Applies every operation in one atomic step. Existence and restore-version
213	  // checks all run against the pre-commit state, so a batch is rejected whole
214	  // if any operation would fail. Title conflicts are checked against the final
215	  // projected set, making swaps and release-then-reuse independent of
216	  // operation order. Each actually-changed document appends one record; a
217	  // normalized-identical replace or restore appends nothing. Returns
218	  // `{ snapshot, changed }` without persisting when `dryRun` is true or the
219	  // batch is content-preserving.
220	  function commitBatch(operations, dryRun) {
221	    // Pre-commit state checks.
222	    for (const op of operations) {
223	      if (op.type === 'create') {
224	        if (current.get(op.document.id)) {
225	          throw new HttpError(409, 'CONFLICT', `document already exists: ${op.document.id}`);
226	        }
227	      } else if (op.type === 'replace') {
228	        if (!current.get(op.document.id)) {
229	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.document.id}`);
230	        }
231	      } else if (op.type === 'delete') {
232	        if (!current.get(op.id)) {
233	          throw new HttpError(404, 'NOT_FOUND', `document not found: ${op.id}`);
234	        }
235	      } else if (op.type === 'restore') {
236	        if (!ledger) {
237	          throw new HttpError(404, 'NOT_FOUND', 'history is not enabled');
238	        }
239	        const chain = ledger.entries(op.id);
240	        if (!chain) {
241	          throw new HttpError(404, 'NOT_FOUND', `document never existed: ${op.id}`);
242	        }
243	        const target = ledger.entry(op.id, op.revision);
244	        if (!target) {
245	          throw new HttpError(404, 'NOT_FOUND', `unknown revision ${op.revision} for document ${op.id}`);
246	        }
247	        if (target.action === 'delete') {
248	          throw new HttpError(400, 'INVALID_REVISION', `revision ${op.revision} of document ${op.id} is a delete and cannot be restored`);
249	        }
250	      }
251	    }
252	
253	    const candidate = new Workspace();
254	    for (const document of current.list()) candidate.add(document);
255	    const nextLedger = ledger ? ledger.clone() : null;
256	
257	    let changed = false;
258	    for (const op of operations) {
259	      if (op.type === 'create') {
260	        candidate.add(op.document);
261	        if (nextLedger) nextLedger.record(op.document.id, 'create', candidate.get(op.document.id));
262	        changed = true;
263	      } else if (op.type === 'replace') {
264	        const before = current.get(op.document.id);
265	        candidate.remove(op.document.id);
266	        candidate.add(op.document);
267	        const stored = candidate.get(op.document.id);
268	        if (!sameDocument(before, stored)) {
269	          if (nextLedger) nextLedger.record(op.document.id, 'replace', stored);
270	          changed = true;
271	        }
272	      } else if (op.type === 'delete') {
273	        candidate.remove(op.id);
274	        if (nextLedger) nextLedger.record(op.id, 'delete', null);
275	        changed = true;
276	      } else if (op.type === 'restore') {
277	        const before = current.get(op.id);
278	        const target = ledger.entry(op.id, op.revision);
279	        candidate.remove(op.id);
280	        candidate.add(target.document);
281	        const stored = candidate.get(op.id);
282	        if (!before || !sameDocument(before, stored)) {
283	          nextLedger.record(op.id, 'restore', stored);
284	          changed = true;
285	        }
286	      }
287	    }
288	
289	    // Title conflicts are checked against the final projected set, so
290	    // operation order cannot make a swap or release-then-reuse fail.
291	    const titles = new Set();
292	    for (const document of candidate.list()) {
293	      if (titles.has(document.title)) {
294	        throw new HttpError(409, 'CONFLICT', `title conflict in batch: ${document.title}`);
295	      }
296	      titles.add(document.title);
297	    }
298	
299	    if (dryRun) {
300	      return { snapshot: candidate.exportJSON(), changed };
301	    }
302	    if (!changed) {
303	      return { snapshot: current.exportJSON(), changed: false };
304	    }
305	
306	    const snapshot = candidate.exportJSON();
307	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
308	    current = candidate;
309	    ledger = nextLedger;
310	    return { snapshot, changed: true };
311	  }
312	
313	  async function createDocument(req, res) {
314	    const text = await readBody(req);
315	    requireIfMatch(req);
316	    const document = validateDocument(parseJson(text));
317	    const snapshot = commit((candidate, nextLedger) => {
318	      if (candidate.get(document.id)) {
319	        throw new HttpError(409, 'CONFLICT', `document already exists: ${document.id}`);
320	      }
321	      assertTitleFree(candidate, document.title);
322	      candidate.add(document);
323	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
324	    });
325	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
326	  }
327	
328	  async function replaceDocument(req, res, id) {
329	    const text = await readBody(req);
330	    requireIfMatch(req);
331	    const document = validateDocument(parseJson(text));
332	    if (document.id !== id) {
333	      throw new HttpError(400, 'ID_MISMATCH', `path id ${id} does not match body id ${document.id}`);
334	    }
335	    if (!current.get(id)) {
336	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
337	    }
338	    const before = current.get(id);
339	    const snapshot = commit((candidate, nextLedger) => {
340	      candidate.remove(id);
341	      assertTitleFree(candidate, document.title);
342	      candidate.add(document);
343	      const stored = candidate.get(id);
344	      // A replace whose normalized content is identical succeeds without
345	      // consuming a revision or touching the files.
346	      if (sameDocument(before, stored)) return false;
347	      if (nextLedger) nextLedger.record(id, 'replace', stored);
348	      return true;
349	    });
350	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
351	  }
352	
353	  function deleteDocument(req, res, id) {
354	    requireIfMatch(req);
355	    if (!current.get(id)) {
356	      throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
357	    }
358	    const snapshot = commit((candidate, nextLedger) => {
359	      candidate.remove(id);
360	      if (nextLedger) nextLedger.record(id, 'delete', null);
361	    });
362	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
363	  }
364	
365	  function historyDocument(req, res, id) {
366	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for GET /documents/${id}/history`);
367	    const entries = ledger.entries(id);
368	    if (!entries) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
369	    sendJson(res, 200, entries, currentEtag());
370	  }
371	
372	  async function restoreDocument(req, res, id) {
373	    if (!ledger) throw new HttpError(404, 'NOT_FOUND', `no route for POST /documents/${id}/restore`);
374	    const text = await readBody(req);
375	    requireIfMatch(req);
376	    let data;
377	    try {
378	      data = JSON.parse(text);
379	    } catch {
380	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
381	    }
382	    if (!data || typeof data !== 'object' || Array.isArray(data)
383	      || Object.keys(data).length !== 1 || !Object.hasOwn(data, 'revision')
384	      || !Number.isInteger(data.revision) || data.revision < 1) {
385	      throw new HttpError(400, 'INVALID_REVISION', 'request body must be an object containing only a positive integer revision');
386	    }
387	    const chain = ledger.entries(id);
388	    if (!chain) throw new HttpError(404, 'NOT_FOUND', `document never existed: ${id}`);
389	    const target = ledger.entry(id, data.revision);
390	    if (!target) throw new HttpError(404, 'NOT_FOUND', `unknown revision ${data.revision} for document ${id}`);
391	    if (target.action === 'delete') {
392	      throw new HttpError(400, 'INVALID_REVISION', `revision ${data.revision} of document ${id} is a delete and cannot be restored`);
393	    }
394	    const before = current.get(id);
395	    const snapshot = commit((candidate, nextLedger) => {
396	      candidate.remove(id);
397	      assertTitleFree(candidate, target.document.title);
398	      candidate.add(target.document);
399	      const stored = candidate.get(id);
400	      // Restoring the already-current content succeeds without a new record.
401	      if (before && sameDocument(before, stored)) return false;
402	      nextLedger.record(id, 'restore', stored);
403	      return true;
404	    });
405	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
406	  }
407	
408	  async function batch(req, res) {
409	    const text = await readBody(req);
410	    requireIfMatch(req);
411	    const data = parseJson(text);
412	    const { operations, dryRun } = validateBatchRequest(data);
413	    const { snapshot } = commitBatch(operations, dryRun);
414	    sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
415	  }
416	
417	  async function handle(req, res) {
418	    const url = new URL(req.url, 'http://127.0.0.1');
419	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
420	    const [resource, id, relation] = segments;
421	
422	    if (resource === 'documents' && segments.length === 1) {
423	      if (req.method === 'GET') {
424	        sendJson(res, 200, current.list(), currentEtag());
425	        return;
426	      }
427	      if (req.method === 'POST') {
428	        await createDocument(req, res);
429	        return;
430	      }
431	    } else if (resource === 'documents' && segments.length === 2) {
432	      if (req.method === 'GET') {
433	        const document = current.get(id);
434	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
435	        sendJson(res, 200, document, currentEtag());
436	        return;
437	      }
438	      if (req.method === 'PUT') {
439	        await replaceDocument(req, res, id);
440	        return;
441	      }
442	      if (req.method === 'DELETE') {
443	        deleteDocument(req, res, id);
444	        return;
445	      }
446	    } else if (resource === 'documents' && segments.length === 3 && relation === 'links' && req.method === 'GET') {
447	      const links = current.links(id);
448	      if (!links) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
449	      sendJson(res, 200, links, currentEtag());
450	      return;
451	    } else if (resource === 'documents' && segments.length === 3 && relation === 'history' && req.method === 'GET') {
452	      historyDocument(req, res, id);
453	      return;
454	    } else if (resource === 'documents' && segments.length === 3 && relation === 'restore' && req.method === 'POST') {
455	      await restoreDocument(req, res, id);
456	      return;
457	    } else if (resource === 'batch' && segments.length === 1 && req.method === 'POST') {
458	      await batch(req, res);
459	      return;
460	    } else if (resource === 'search' && segments.length === 1 && req.method === 'GET') {
461	      sendJson(res, 200, current.search(url.searchParams.get('q') ?? ''), currentEtag());
462	      return;
463	    }
464	    throw new HttpError(404, 'NOT_FOUND', `no route for ${req.method} ${url.pathname}`);
465	  }
466	
467	  const server = http.createServer((req, res) => {
468	    handle(req, res).catch((error) => {
469	      if (res.headersSent) {
470	        res.destroy(error);
471	        return;
472	      }
473	      const status = error instanceof HttpError ? error.status : 500;
474	      const code = error instanceof HttpError ? error.code
475	        : error instanceof SnapshotError ? error.code
476	          : 'INTERNAL_ERROR';
477	      sendJson(res, status, { code, message: error.message });
478	    });
479	  });
480	  return server;
481	}
