57	async function startServerFailure(args, { cwd } = {}) {
58	  const child = spawn(process.execPath, [CLI, 'serve', ...args], { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
59	  let stdout = '';
60	  let stderr = '';
61	  child.stdout.on('data', (chunk) => { stdout += chunk; });
62	  child.stderr.on('data', (chunk) => { stderr += chunk; });
63	  const status = await new Promise((resolve) => child.on('exit', resolve));
64	  return { status, stdout, stderr };
65	}
66	
67	async function request(base, method, route, { body, rawBody, headers = {} } = {}) {
68	  const response = await fetch(`${base}${route}`, {
69	    method,
70	    headers: {
71	      ...(body !== undefined || rawBody !== undefined ? { 'content-type': 'application/json' } : {}),
72	      ...headers,
73	    },
74	    body: rawBody ?? (body !== undefined ? JSON.stringify(body) : undefined),
75	  });
76	  const text = await response.text();
77	  return {
78	    status: response.status,
79	    etag: response.headers.get('etag'),
80	    body: text ? JSON.parse(text) : null,
81	  };
82	}
