112	    const created = await request(server.url, 'POST', '/documents', {
113	      body: { id: 'a', title: 'A', body: 'links [[b]]', tags: ['Intro', 'intro'] },
114	      headers: { 'if-match': empty.etag },
115	    });
116	    assert.equal(created.status, 201);
117	    assert.equal(created.etag, `"${created.body.checksum}"`);
118	    assert.equal(created.body.version, 1);
119	    assert.deepEqual(created.body.documents, [
120	      { id: 'a', title: 'A', body: 'links [[b]]', tags: ['intro'] },
121	    ]);
122	    assert.ok(fs.existsSync(file));
123	
124	    // The written file is importable through the existing snapshot API.
125	    const reimported = new Workspace();
