132	  // A restarted server reads the saved content back.
133	  const restarted = await startServer([file, '--port', '0']);
134	  try {
135	    const listed = await request(restarted.url, 'GET', '/documents');
136	    assert.deepEqual(listed.body.map((document) => document.id), ['a']);
137	    const single = await request(restarted.url, 'GET', '/documents/a');
138	    assert.equal(single.status, 200);
139	    assert.equal(single.body.body, 'links [[b]]');
140	    assert.equal(single.etag, `"${createdChecksum(file)}"`);
141	  } finally {
142	    await restarted.stop();
143	  }
144	});
